<template>
  <view class="page">
    <view class="topbar"><view><text class="eyebrow">MERCHANT WORKSPACE</text><text class="title">核销工作台</text></view><view class="top-actions"><view class="bell" @tap="goNotifications"><text class="bell-glyph iconfont icon-lingdang-xianxing"/><text v-if="unreadCount" class="unread-dot"/></view><view class="avatar" @tap="showAccount = !showAccount">{{ firstLetter }}</view></view></view>
    <view v-if="showAccount" class="account-pop"><text>{{ merchantName }}</text><text @tap="logout">退出登录</text></view>
    <view class="content">
      <view class="metrics"><view><text>今日已核销</text><text>{{ todayVerifiedOrders.length }}</text><text>笔订单</text></view><view class="divider"/><view><text>今日核销金额</text><text><i>¥</i>{{ todayVerifiedAmount.toFixed(2) }}</text><text>实时统计</text></view></view>
      <view class="verify-hero"><view class="hero-orbit"><view class="scan-button" @tap="startScan"><text class="scan-icon iconfont icon-lijihexiao"/><text>立即核销</text><text>扫码识别消费券</text></view></view><button class="manual-button" @tap="openManual"><text>⌨</text> 手动输入核销码</button></view>
      <view class="section-head"><view><text>待核销订单</text><text>{{ pendingOrders.length }} 笔待处理</text></view><text @tap="goOrders">查看全部 →</text></view>
      <view v-if="pendingOrders.length" class="order-list">
        <view v-for="order in pendingOrders.slice(0,3)" :key="order.id" class="order-card" :class="{ urgent: order.table === 'C08' }" @tap="selectedOrder = order">
          <view class="order-main"><text>{{ order.packageName }}</text><text class="status">{{ order.table === 'C08' ? '等待超时' : '待核销' }}</text><text class="table">{{ order.table }}桌</text><text class="time">{{ order.time }}</text></view>
          <view class="order-customer"><text>{{ order.customer }} · {{ order.phone.slice(-4) }}</text><text>›</text></view><view class="voucher"><text>▣</text><text>券码 {{ formatCode(order.voucherCode) }}</text></view>
        </view>
      </view>
      <view v-else class="empty"><text>✓</text><text>今日暂无待核销订单</text></view>
    </view>
    <merchant-tabbar active="verify"/>
    <merchant-order-detail :order="selectedOrder" @close="selectedOrder=null" @verify="confirmVerification"/>
    <view v-if="manualVisible" class="manual-mask" @tap="closeManual">
      <view class="manual-sheet" @tap.stop>
        <view class="handle"/>
        <view class="manual-head"><view class="manual-title"><view class="keyboard-icon">⌨</view><view><text>手动输入核销码</text><text>请输入顾客出示的 8 位数字券码</text></view></view><text class="manual-close" @tap="closeManual">×</text></view>
        <view class="code-panel" :class="{ error: manualError }"><view class="code-slots"><view v-for="index in 8" :key="index" class="code-slot" :class="{ filled: manualCode[index-1], current: manualCode.length===index-1&&!manualError }">{{ manualCode[index-1] || '' }}</view></view><view class="code-feedback"><text v-if="manualError" class="feedback-error">! {{ manualError }}</text><text v-else>{{ manualCode.length ? `已输入 ${manualCode.length}/8 位` : '请按下方数字键盘输入' }}</text></view></view>
        <view class="keypad"><button v-for="key in keys" :key="key" :class="{ utility: key === '清空' || key === '⌫', danger: key === '清空' }" hover-class="key-pressed" @tap="pressKey(key)">{{ key }}</button></view>
        <button class="code-confirm" :disabled="manualCode.length!==8" @tap="lookupCode"><text>{{ manualCode.length===8?'查询并核销':'请输入完整券码' }}</text><text>→</text></button>
        <text class="manual-safe-tip">核销前将展示订单详情，请确认无误后操作</text>
      </view>
    </view>
  </view>
</template>

<script setup>
import { computed, ref } from 'vue'
import { onShow } from '@dcloudio/uni-app'
import MerchantOrderDetail from '../../components/merchant-order-detail.vue'
import MerchantTabbar from '../../components/merchant-tabbar.vue'
import { normalizeVoucherCode, useMerchantVerification } from '../../composables/use-merchant-verification'
import { enforcePortal } from '../../core/route-guard'
import { clearSession, session, updateSessionUser } from '../../core/session'
import { getCurrentAccount, unwrap } from '../../services/agent'
import { logout as requestLogout } from '../../services/auth'

const { pendingOrders, todayVerifiedOrders, todayVerifiedAmount, unreadCount, findByCode, verifyOrder } = useMerchantVerification()
const remoteName=ref(''),selectedOrder=ref(null),manualVisible=ref(false),manualCode=ref(''),manualError=ref(''),showAccount=ref(false)
const keys=['1','2','3','4','5','6','7','8','9','清空','0','⌫']
const merchantName=computed(()=>remoteName.value||session.user?.name||'商家')
const firstLetter=computed(()=>merchantName.value.slice(0,1))
onShow(()=>{if(!enforcePortal('merchant'))return;if(!String(session.token).startsWith('local-session-'))loadAccount()})
async function loadAccount(){try{const data=unwrap(await getCurrentAccount())||{},merchant=data.merchant||data.account?.merchant||{},user=data.user||data.account?.user||{};remoteName.value=merchant.name||user.name||'';if(remoteName.value)updateSessionUser({...merchant,name:remoteName.value})}catch(error){if(!session.user)uni.showToast({title:error.message||'商家资料加载失败',icon:'none'})}}
function formatCode(code){return String(code).replace(/(\d{4})(?=\d)/g,'$1 ')}
function goOrders(){uni.navigateTo({url:'/pages/merchant/orders'})} function goNotifications(){uni.navigateTo({url:'/pages/merchant/notifications'})}
function openManual(){manualCode.value='';manualError.value='';manualVisible.value=true} function closeManual(){manualVisible.value=false}
function pressKey(key){manualError.value='';if(key==='清空')manualCode.value='';else if(key==='⌫')manualCode.value=manualCode.value.slice(0,-1);else if(manualCode.value.length<8)manualCode.value+=key}
function lookupCode(){const order=findByCode(manualCode.value);if(!order){manualError.value='未查询到该券码，请核对后重试';return}manualVisible.value=false;selectedOrder.value=order}
function startScan(){
  // #ifdef H5
  openManual();uni.showToast({title:'H5 环境请手动输入券码',icon:'none'});return
  // #endif
  uni.scanCode({onlyFromCamera:false,scanType:['qrCode'],success:({result})=>{const code=normalizeVoucherCode(result);if(code.length!==8){uni.showToast({title:'未识别到有效核销码',icon:'none'});return}manualCode.value=code;lookupCode()},fail:(error)=>{if(!String(error.errMsg||'').includes('cancel'))uni.showToast({title:'扫码失败，请重试',icon:'none'})}})
}
function confirmVerification(order){uni.showModal({title:'确认核销',content:`确认核销“${order.packageName}”吗？核销后不可撤销。`,confirmText:'确认核销',success:({confirm})=>{if(!confirm)return;const result=verifyOrder(order.id);selectedOrder.value=result.order||null;uni.showToast({title:result.message,icon:result.ok?'success':'none'})}})}
async function logout(){try{if(!String(session.token).startsWith('local-session-'))await requestLogout()}catch{}clearSession();uni.reLaunch({url:'/pages/auth/login?portal=merchant'})}
</script>

<style lang="scss" scoped>
