50%;background:radial-gradient(circle,#d5faee 0,#d5faee 54%,#ecfaf5 55%,#ecfaf5 69%,transparent 70%)}.scan-button{display:flex;flex-direction:column;align-items:center;justify-content:center;width:205rpx;height:205rpx;border-radius:50%;background:linear-gradient(145deg,#0da577,#19bd8c);color:#fff;box-shadow:0 18rpx 38rpx rgba(14,164,120,.25)}.scan-icon{font-size:43rpx!important}.scan-button text:nth-child(2){font-size:29rpx;font-weight:800}.scan-button text:last-child{margin-top:7rpx;color:#d9fff2;font-size:18rpx}.manual-button{width:315rpx;margin:16rpx auto 0;border:1rpx solid #38ad8c;border-radius:15rpx;background:#fff;color:#118363;font-size:22rpx;line-height:71rpx}.manual-button::after{border:0}.section-head{display:flex;align-items:flex-end;justify-content:space-between;margin:3rpx 3rpx 20rpx}.section-head>view text:first-child{font-size:29rpx;font-weight:800}.section-head>view text:last-child{margin-top:5rpx;color:#94a19d;font-size:18rpx}.section-head>text{color:#0b9270;font-size:21rpx}.order-list{display:flex;flex-direction:column;gap:16rpx}.order-card{padding:22rpx 24rpx;border:1rpx solid #dce6e2;border-radius:20rpx;background:#fff}.order-card.urgent{border-color:#ef8d87}.order-main{display:flex;align-items:center;gap:9rpx}.order-main>text:first-child{max-width:245rpx;overflow:hidden;font-size:24rpx;font-weight:750;white-space:nowrap}.status,.table{padding:5rpx 10rpx;border-radius:10rpx;font-size:16rpx}.status{background:#ddf8e9;color:#15805d}.urgent .status{background:#ffe0de;color:#cc4842}.table{background:#eef3f1;color:#52675f}.time{margin-left:auto;color:#71847d;font-size:18rpx}.order-customer{display:flex;justify-content:space-between;margin-top:13rpx;color:#7e908a;font-size:20rpx}.order-customer text:last-child{font-size:33rpx;line-height:20rpx}.voucher{display:flex;gap:7rpx;margin-top:8rpx;color:#087b59;font-size:21rpx;font-weight:750}.empty{padding:55rpx;border-radius:20rpx;background:#fff;text-align:center}.empty text:first-child{color:#17ac80;font-size:38rpx}.empty text:last-child{margin-top:10rpx;color:#82938d;font-size:21rpx}.manual-mask{position:fixed;z-index:60;inset:0;display:flex;align-items:flex-end;background:rgba(12,37,30,.48)}.manual-sheet{width:100%;padding:14rpx 31rpx calc(28rpx + env(safe-area-inset-bottom));border-radius:30rpx 30rpx 0 0;background:#fff;box-sizing:border-box}.handle{width:66rpx;height:7rpx;margin:0 auto 19rpx;border-radius:7rpx;background:#d6dfdc}.manual-head{display:flex;justify-content:space-between}.manual-head>view text:first-child{font-size:29rpx;font-weight:800}.manual-head>view text:last-child{margin-top:7rpx;color:#92a09b;font-size:19rpx}.manual-head>text{color:#8b9994;font-size:43rpx}.code-display{margin:24rpx 0 17rpx;padding:21rpx;border:1rpx solid #dfe7e4;border-radius:15rpx;background:#f8faf9;text-align:center}.code-display text:first-child{color:#1a6c55;font-family:monospace;font-size:31rpx;font-weight:800;letter-spacing:7rpx}.code-display text:last-child{margin-top:7rpx;color:#d34f49;font-size:19rpx}.code-display.error{border-color:#ed9d98}.keypad{display:grid;grid-template-columns:repeat(3,1fr);gap:10rpx}.keypad button{border-radius:13rpx;background:#f5f8f7;color:#29483f;font-size:27rpx;font-weight:700;line-height:68rpx}.keypad button::after{border:0}.keypad button.utility{color:#758780;font-size:20rpx}.code-confirm{margin-top:16rpx;border-radius:14rpx;background:#0b9971;color:#fff;font-size:24rpx;font-weight:700;line-height:80rpx}.code-confirm[disabled]{opacity:.45}.code-confirm::after{border:0}
.manual-mask{background:rgba(9,32,25,.58);backdrop-filter:blur(3rpx)}
.manual-sheet{max-width:720rpx;margin:0 auto;padding:13rpx 30rpx calc(22rpx + env(safe-area-inset-bottom));border-radius:34rpx 34rpx 0 0;box-shadow:0 -18rpx 60rpx rgba(6,38,29,.16)}
.scan-icon{font-size:54rpx!important}
.handle{width:70rpx;margin-bottom:23rpx}
.manual-head{align-items:center}.manual-title{display:flex;align-items:center;gap:15rpx}.keyboard-icon{display:flex;align-items:center;justify-content:center;width:58rpx;height:58rpx;border-radius:17rpx;background:#e2f7f0;color:#098b66;font-size:27rpx}.manual-title>view:last-child text{display:block}.manual-title>view:last-child text:first-child{color:#193c32;font-size:28rpx;font-weight:850}.manual-title>view:last-child text:last-child{margin-top:5rpx;color:#8d9c97;font-size:18rpx}.manual-close{display:flex;align-items:center;justify-content:center;width:56rpx;height:56rpx;border-radius:50%;background:#f3f6f5;color:#7c8e87;font-size:37rpx;font-weight:300}
.code-panel{margin:24rpx 0 18rpx;padding:19rpx 16rpx 13rpx;border:1rpx solid #dae6e2;border-radius:18rpx;background:#f7faf9;transition:.2s}.code-panel.error{border-color:#e99b96;background:#fff7f6}.code-slots{display:flex;justify-content:center;gap:8rpx}.code-slot{display:flex;align-items:center;justify-content:center;width:58rpx;height:67rpx;border:2rpx solid #d6e2de;border-radius:12rpx;background:#fff;color:#0a7657;font-family:monospace;font-size:30rpx;font-weight:850;box-sizing:border-box}.code-slot.filled{border-color:#8fd6c0;background:#eefaf6}.code-slot.current{border-color:#0b9a72;box-shadow:0 0 0 5rpx rgba(11,154,114,.1)}.code-panel.error .code-slot{border-color:#f0c9c6;background:#fff}.code-feedback{height:29rpx;margin-top:11rpx;color:#91a09b;text-align:center;font-size:17rpx;line-height:29rpx}.feedback-error{color:#cf4d47;font-weight:650}
.keypad{gap:12rpx}.keypad button{height:76rpx;margin:0;border:1rpx solid #edf1ef;border-radius:15rpx;background:#f5f8f7;color:#24483e;font-size:28rpx;font-weight:800;line-height:74rpx;box-shadow:0 4rpx 10rpx rgba(20,66,53,.035)}.keypad button.utility{background:#edf3f1;color:#647871;font-size:19rpx;font-weight:700}.keypad button.danger{color:#b15d59}.keypad .key-pressed{background:#dff4ed;transform:scale(.97)}
.code-confirm{display:flex;align-items:center;justify-content:center;gap:14rpx;height:84rpx;margin-top:17rpx;border-radius:16rpx;background:linear-gradient(135deg,#087d5c,#0ba878);font-size:23rpx;font-weight:800;line-height:84rpx;box-shadow:0 11rpx 22rpx rgba(9,145,105,.18)}.code-confirm text:last-child{font-size:30rpx}.code-confirm[disabled]{background:#edf1f0;color:#adb7b3;opacity:1;box-shadow:none}.manual-safe-tip{display:block;margin-top:12rpx;color:#a0aba7;text-align:center;font-size:16rpx}
.bell>.bell-glyph{position:static;width:auto;height:auto;border:0;background:transparent;color:#31584d;font-size:32rpx;line-height:1}.bell>.unread-dot{position:absolute;top:11rpx;right:12rpx;width:12rpx;height:12rpx;border:3rpx solid #fff;border-radius:50%;background:#ec5a54}
</style>
